specimens.css:
/* 状态模拟：:focus-visible 无法静态触发，下面是 Checkbox.module.css 中 `.checkbox input:focus-visible` 的原样副本。 */
.checkbox input.forceFocus {
  outline: var(--dsw-focus-ring-width) solid var(--dsw-focus-ring-color, var(--dsw-alias-state-business-primary));
  outline-offset: 2px;
}

/* 状态模拟：:hover 无法静态触发，下面是 `.tab:hover:not(:disabled)` 分支的原样副本。 */
.tab.forceHover:not(:disabled) {
  color: var(--dsw-alias-label-primary);
}

/* 状态模拟：:hover 无法静态触发，下面是 `.tab:hover, .tab[aria-selected='true']` 中悬停分支的原样副本。 */
.tab.forceHover {
  background: transparent;
  color: var(--dsw-alias-label-primary);
}

/* 状态模拟：组件用 autoFocus 在挂载时获焦，静态示例无法触发 :focus，下面是 `.editor:focus` 的原样副本。 */
.editor.forceFocus {
  border-color: var(--dsw-alias-state-business-primary);
}

/* 状态模拟：:focus-within 无法静态触发，下面是 `.wrap:focus-within` 的原样副本。 */
.wrap.forceFocus {
  border-color: var(--dsw-alias-state-business-primary);
}

/* 静态近似：tooltip 变体的键帽是给深色气泡用的，底色与文字色由 Tooltip.module.css 的 .bubble 提供（--dsw-alias-tooltip-bg / --dsw-static-neutral-bluish-00）。这里把该规则原样搬来，只去掉 position: fixed 以便在示例里排布。 */
.bubbleContext {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 3px 7px;
  border-radius: var(--dsw-radius-sm);
  background: var(--dsw-alias-tooltip-bg);
  color: var(--dsw-static-neutral-bluish-00);
  font-size: 13px;
  line-height: 20px;
}

/* 静态近似：同上，气泡底色与文字色取自 Tooltip 的 .bubble。 */
.bubbleContext {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 3px 7px;
  border-radius: var(--dsw-radius-sm);
  background: var(--dsw-alias-tooltip-bg);
  color: var(--dsw-static-neutral-bluish-00);
  font-size: 13px;
  line-height: 20px;
}

/* 状态模拟：:hover / :active 无法静态触发，下面是 `.warning:hover` 与 `.warning:active` 的原样副本。 */
.warning.forceHover {
  background: color-mix(
    in srgb,
    var(--dsw-alias-state-warn-tertiary),
    var(--dsw-alias-state-warn-primary) 6%
  );
}
.warning.forceActive {
  background: color-mix(
    in srgb,
    var(--dsw-alias-state-warn-tertiary),
    var(--dsw-alias-state-warn-primary) 10%
  );
}

/* 静态近似：真实行里这个 2px 圆点由调用方 CSS 提供（ToolRow.module.css 的 .sep），
   这里按同值补一条，让基础层与高亮层都能看到它；高亮层由 .sweep [data-shimmer-decoration] 改成 currentColor。 */
.separatorDot {
  flex: none;
  width: 2px;
  height: 2px;
  border-radius: 1px;
  margin: 0 8px;
  background: var(--dsw-alias-label-caption);
}
